// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        // 1. Keep amounts in a wide, meaningful range.
        depositAmount = bound(depositAmount, 1, 1 ether);
        collectAmount = bound(collectAmount, 1, depositAmount);

        // 2. Deploy a LogFile recorder so Deposit/Collect's external calls to Log do not revert.
        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        // 3. Use a fresh fuzzed actor as the caller/collector.
        address actor = makeAddr("actor");
        vm.deal(actor, depositAmount);

        // 4. Deposit to establish the balance that Collect will withdraw from.
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // 5. Collect as the actor.
        uint256 balanceBefore = address(actor).balance;
        vm.prank(actor);
        c.Collect(collectAmount);
        uint256 balanceAfter = address(actor).balance;

        // Reference: Collect sends exactly collectAmount back to the caller.
        // Mutant: Collect sends 0 and only decreases `c.balances[actor]`.
        assertTrue(balanceAfter - balanceBefore == collectAmount);
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
